import time
from socket import socket, AF_INET, SOCK_STREAM
from taf.hw.rf_switch.devices.rf_switch import RfSwitch
from taf.hw.rf_switch.exceptions import RfSwitchActionFailed, RfSwitchActionNotSupported


class JIEXI(RfSwitch):
    """
    Module to control Jiexi types based RF switches.
    """
    def __init__(self, ip, port=3000):
        super().__init__()
        self.ip = ip
        self.port = int(port)
        self.client_socket = socket(AF_INET, SOCK_STREAM)
        self.client_socket.settimeout(30.0)
        self.client_socket.connect((self.ip, self.port))

    def disconnect_ports(self, port_in, port_out='1'):
        msg = "Action not supported for this device."
        raise RfSwitchActionNotSupported(msg)

    def _send_command(self, command):
        command += "\r\n"
        command = command.encode()
        self.client_socket.send(command)

    def _execute_command(self, command):
        self._send_command(command)
        recv = self.client_socket.recv(1024)
        if len(recv) == 0:
            raise RfSwitchActionFailed("Received empty response from the device.")
        return recv


class RTS(JIEXI):
    SUPPORTED_PORT_IN_VALUES = [str(value) for value in range(1, 65)]
    SUPPORTED_PORT_OUT_VALUES = (None, "1")
    """
    Module to control TopYoung JIEXI RTS types based RF switches.
    """
    def __init__(self, ip, port=3000):
        super().__init__(ip, port)

    def connect_ports(self, port_in, port_out='1'):
        if port_in not in self.SUPPORTED_PORT_IN_VALUES:
            error_msg = f'Given port_in: {port_in} is not supported.'
            raise RfSwitchActionFailed(error_msg)
        if port_out not in self.SUPPORTED_PORT_OUT_VALUES:
            raise RfSwitchActionFailed(f'Given port_out: {port_out} is not supported.')
        recv = self._execute_command('*IDN?')
        if "RTS" in recv.decode():
            self._operate_ports(port_in)
        else:
            msg = "Expected vendor: RTS not found in device response"
            raise RfSwitchActionFailed(msg)

    def get_port_in_status(self, port_in):
        connected_port_in = self.get_port_out_status(port_out="1")
        if port_in == connected_port_in:
            return "1"

    def get_port_out_status(self, port_out="1"):
        if port_out not in self.SUPPORTED_PORT_OUT_VALUES:
            raise RfSwitchActionFailed(f'Given port_out: {port_out} is not supported.')
        query_command = 'SWITch:STATus? 9'
        end_switch_port_in = self._execute_command(query_command)
        end_switch_port_in = end_switch_port_in.decode()
        time.sleep(0.2)
        query_command = f'SWITch:STATus? {end_switch_port_in}'
        fir_switch_port_in = self._execute_command(query_command)
        fir_switch_port_in = fir_switch_port_in.decode()
        port_in = int(fir_switch_port_in) + (int(end_switch_port_in) - 1) * 8
        return str(port_in)

    def get_connected_ports(self):
        port_in = self.get_port_out_status(port_out="1")
        return {port_in: "1"}

    def _operate_ports(self, port_in):
        port_in = int(port_in)
        remainder = port_in % 8
        if remainder == 0:
            SwitchID1 = port_in // 8
            PinID1 = 8
        else:
            SwitchID1 = port_in // 8 + 1
            PinID1 = remainder
        SwitchID2 = 9
        PinID2 = SwitchID1
        closeCmd1 = f'SWITch:CLOSe {SwitchID1},{PinID1}'
        closeCmd2 = f'SWITch:CLOSe {SwitchID2},{PinID2}'
        self._send_command(closeCmd1)
        time.sleep(0.2)
        self._send_command(closeCmd2)


class TSS65(JIEXI):
    SUPPORTED_PORT_IN_VALUES = [str(value) for value in range(1, 66)]
    SUPPORTED_PORT_OUT_VALUES = [str(value) for value in range(1, 3)]
    """
    Module to control TopYoung JIEXI TSS65types based RF switches.
    """
    def __init__(self, ip, port=3000):
        super().__init__(ip, port)

    def connect_ports(self, port_in, port_out):
        if port_in not in self.SUPPORTED_PORT_IN_VALUES:
            error_msg = f'Given port_in: {port_in} is not supported.'
            raise RfSwitchActionFailed(error_msg)
        if port_out not in self.SUPPORTED_PORT_OUT_VALUES:
            raise RfSwitchActionFailed(f'Given port_out: {port_out} is not supported.')
        recv = self._execute_command('*IDN?')
        if "TSS65B2" in recv.decode():
            self._operate_ports(port_in, port_out)
        else:
            msg = "Expected model: JIEXI TSS65B2-6E1-70S-ES not found in device response"
            raise RfSwitchActionFailed(msg)

    def get_port_in_status(self, port_in):
        """get_port_in_status not support due to hw not support"""
        msg = "Action not implemented for this device, please contact library maintainers if it is needed."
        raise RfSwitchActionNotSupported(msg)

    def get_port_out_status(self, port_out):
        """not support due to hw not support"""
        msg = "Action not implemented for this device, please contact library maintainers if it is needed."
        raise RfSwitchActionNotSupported(msg)

    def get_connected_ports(self):
        """ not support due to hw not support"""
        msg = "Action not implemented for this device, please contact library maintainers if it is needed."
        raise RfSwitchActionNotSupported(msg)

    def _operate_ports(self, port_in, port_out):
        port_in = int(port_in)
        port_out = int(port_out)
        if 1 <= port_in <= 64:
            in_sw_num = ((port_in - 1) // 8 + 1)
            pin = port_in % 8
            if pin == 0:
                in_sw_pin = 8
            else:
                in_sw_pin = pin
            out_sel_sw_num = in_sw_num + 8
            out_sel_sw_pin = port_out
            in_sel_sw_num = port_out + 17
            in_sel_sw_pin = in_sw_num
            cal_in_sw_num = port_out + 19
            cal_in_sw_pin = 1
            sw_command = f'SETSW:{in_sw_num}:{in_sw_pin}'
            self._execute_command(sw_command)
            time.sleep(0.2)
            sw_command = f'SETSW:{out_sel_sw_num}:{out_sel_sw_pin}'
            self._execute_command(sw_command)
            time.sleep(0.2)
            sw_command = f'SETSW:{in_sel_sw_num}:{in_sel_sw_pin}'
            self._execute_command(sw_command)
            time.sleep(0.2)
            sw_command = f'SETSW:{cal_in_sw_num}:{cal_in_sw_pin}'
            self._execute_command(sw_command)
        else:
            cal_out_sw_num = 17
            cal_out_sw_pin = port_out
            cal_in_sw_num = port_out + 19
            cal_in_sw_pin = 2
            sw_command = f'SETSW:{cal_out_sw_num}:{cal_out_sw_pin}'
            self._execute_command(sw_command)
            time.sleep(0.2)
            sw_command = f'SETSW:{cal_in_sw_num}:{cal_in_sw_pin}'
            self._execute_command(sw_command)


class TSS32(JIEXI):
    SUPPORTED_PORT_IN_VALUES = [str(value) for value in range(1, 33)]
    SUPPORTED_PORT_OUT_VALUES = (None, "1")
    """
    Module to control TopYoung JIEXI TSS32 types based RF switches.
    """
    def __init__(self, ip, port=3000):
        super().__init__(ip, port)

    def connect_ports(self, port_in, port_out="1"):
        if port_in not in self.SUPPORTED_PORT_IN_VALUES:
            error_msg = f'Given port_in: {port_in} is not supported.'
            raise RfSwitchActionFailed(error_msg)
        if port_out not in self.SUPPORTED_PORT_OUT_VALUES:
            raise RfSwitchActionFailed(f'Given port_out: {port_out} is not supported.')
        recv = self._execute_command('*IDN?')
        if "TSS32T1" in recv.decode():
            self._operate_ports(port_in)
        else:
            msg = "Expected model:JIEXI TSS32T1-18B1-60S-ES not found in device response"
            raise RfSwitchActionFailed(msg)

    def get_port_in_status(self, port_in):
        connected_port_in = self.get_port_out_status(port_out="1")
        if port_in == connected_port_in:
            return "1"

    def get_port_out_status(self, port_out="1"):
        if port_out not in self.SUPPORTED_PORT_OUT_VALUES:
            raise RfSwitchActionFailed(f'Given port_out: {port_out} is not supported.')
        query_command = 'SWITch:STATus? 5'
        end_switch_port_in = self._execute_command(query_command)
        time.sleep(0.2)
        if int(end_switch_port_in) <= 2:
            query_command = f'SWITch:STATus? {end_switch_port_in.decode()}'
        else:
            query_command = f'SWITch:STATus? {int(end_switch_port_in.decode()) - 1}'
        fir_switch_port_in = self._execute_command(query_command)
        end_switch_port_in = int(end_switch_port_in)
        fir_switch_port_in = int(fir_switch_port_in)
        if 1 <= end_switch_port_in <= 2:
            port_in = fir_switch_port_in + (end_switch_port_in - 1) * 8
        else:
            port_in = fir_switch_port_in + (end_switch_port_in - 2) * 8
        return str(port_in)

    def get_connected_ports(self):
        port_in = self.get_port_out_status(port_out="1")
        return {port_in: "1"}

    def _operate_ports(self, port_in):
        port_num = int(port_in)
        remainder = port_num % 8
        if remainder == 0:
            SwitchID1 = port_num // 8
            PinID1 = 8
        else:
            SwitchID1 = port_num // 8 + 1
            PinID1 = remainder
        if (SwitchID1 >= 3):
            PinID2 = SwitchID1 + 1
        else:
            PinID2 = SwitchID1
        SwitchID2 = 5
        closeCmd1 = f'SWITch:CLOSe {SwitchID1},{PinID1}'
        closeCmd2 = f'SWITch:CLOSe {SwitchID2},{PinID2}'
        self._send_command(closeCmd1)
        time.sleep(0.2)
        self._send_command(closeCmd2)


class TSS8T1(JIEXI):
    SUPPORTED_PORT_IN_VALUES = [str(value) for value in range(1, 9)]
    SUPPORTED_PORT_OUT_VALUES = (None, "1")
    """
    Module to control TopYoung JIEXI TSS8T1 types based RF switches.
    """
    def __init__(self, ip, port=3000):
        super().__init__(ip, port)

    def connect_ports(self, port_in, port_out="1"):
        if port_in not in self.SUPPORTED_PORT_IN_VALUES:
            error_msg = f'Given port_in: {port_in} is not supported.'
            raise RfSwitchActionFailed(error_msg)
        if port_out not in self.SUPPORTED_PORT_OUT_VALUES:
            raise RfSwitchActionFailed(f'Given port_out: {port_out} is not supported.')
        recv = self._execute_command('*IDN?')
        if "TSS8T1" in recv.decode():
            self._operate_ports(port_in)
        else:
            msg = "Expected model:JIEXI TSS8T1-0.1G6-70N-ES not found in device response"
            raise RfSwitchActionFailed(msg)

    def get_port_in_status(self, port_in):
        connected_port_in = self.get_port_out_status(port_out="1")
        if port_in == connected_port_in:
            return "1"

    def get_port_out_status(self, port_out="1"):
        if port_out not in self.SUPPORTED_PORT_OUT_VALUES:
            raise RfSwitchActionFailed(f'Given port_out: {port_out} is not supported.')
        query_command = 'SWITch:STATus? 1'
        port_in = self._execute_command(query_command)
        return str(port_in)

    def get_connected_ports(self):
        port_in = self.get_port_out_status(port_out="1")
        return {port_in: "1"}

    def _operate_ports(self, port_in):
        """
        Here "SWITch:CLOSe" means switch to target port and connect this port to work.
        """
        port_num = int(port_in)
        closeCmd1 = f'SWITch:CLOSe 1,{port_num}'
        self._send_command(closeCmd1)


class TPS16X(JIEXI):
    SUPPORTED_PORT_IN_VALUES = [str(value) for value in range(1, 16)]
    SUPPORTED_PORT_OUT_VALUES = (None, "1")
    """
    Module to control TopYoung JIEXI TPS16X types based RF switches.
    """
    def __init__(self, ip, port=3000):
        super().__init__(ip, port)

    def connect_ports(self, port_in, port_out="1"):
        if port_in not in self.SUPPORTED_PORT_IN_VALUES:
            error_msg = f'Given port_in: {port_in} is not supported.'
            raise RfSwitchActionFailed(error_msg)
        if port_out not in self.SUPPORTED_PORT_OUT_VALUES:
            raise RfSwitchActionFailed(f'Given port_out: {port_out} is not supported.')
        recv = self._execute_command('*IDN?')
        if "TPS16X" in recv.decode():
            self._operate_ports(port_in)
        else:
            msg = "Expected model:JIEXI TPS16X-0.4G8.5-60S-P not found in device response"
            raise RfSwitchActionFailed(msg)

    def get_port_in_status(self, port_in):
        connected_port_in = self.get_port_out_status(port_out="1")
        if port_in == connected_port_in:
            return "1"

    def get_port_out_status(self, port_out="1"):
        if port_out not in self.SUPPORTED_PORT_OUT_VALUES:
            raise RfSwitchActionFailed(f'Given port_out: {port_out} is not supported.')
        query_command = 'READROUTE'
        port_in = self._execute_command(query_command)
        return str(port_in)

    def get_connected_ports(self):
        port_in = self.get_port_out_status(port_out="1")
        return {port_in: "1"}

    def _operate_ports(self, port_in):
        """
        Here "ROUTE:PATHSWITCH:T1:S{port_num}:0" means switch to target port and connect this port to work.
        """
        port_num = int(port_in)
        close_cmd = f'ROUTE:PATHSWITCH:T1:S{port_num}:0'
        self._execute_command(close_cmd)
